import { CurrentUserDto } from '@abp/ng.core';
import { ToasterService } from '@abp/ng.theme.shared';
import { Component, Input, OnInit } from '@angular/core';
import { firstValueFrom, takeUntil } from 'rxjs';
import { RoleDto, UserDto } from 'src/app/services/users/models';
import { UserServiceService } from 'src/app/services/users/user-service.service';
import { CurrentUserServiceService } from 'src/app/services/utils/current-user-service/current-user-service.service';
import { NgbModalRef } from '@ng-bootstrap/ng-bootstrap';

@Component({
  selector: 'app-user-add-or-update',
  templateUrl: './user-add-or-update.component.html',
  styleUrl: './user-add-or-update.component.scss',
})
export class UserAddOrUpdateComponent implements OnInit {
  //#region fields
  @Input() data: any;
  @Input() modalRef: NgbModalRef;
  user: UserDto = {
    userName: null,
    tenantId: null,
    name: null,
    password: null,
    surname: null,
    email: null,
    emailConfirmed: null,
    phoneNumber: null,
    phoneNumberConfirmed: null,
    isActive: true,
    lockoutEnd: null,
    lockoutEnabled: true,
    extraProperties: {
      IsAdmin: false,
      CustomerNo: '',
    },
    concurrencyStamp: null,
    creationTime: null,
    creatorId: null,
    lastModificationTime: null,
    lastModifierId: null,
    isDeleted: null,
    deleterId: null,
    deletionTime: null,
  };
  roles: RoleDto[];
  userRoles: RoleDto[] = [];
  currentUser: CurrentUserDto;

  //#endregion

  //#region ctor
  constructor(
    private userService: UserServiceService,
    public currentUserInfoService: CurrentUserServiceService,
    private toaster: ToasterService
  ) {
    this.currentUser = this.currentUserInfoService.currentUser.value;
  }

  //#endregion

  //#region utils

  async getUserById(id: string): Promise<void> {
    this.user = await firstValueFrom(this.userService.get(id));
  }
  async loadRoles(): Promise<void> {
    this.roles = (await firstValueFrom(this.userService.getRoles())).items;

    if (this.data.id == null) {
      this.roles.filter(r => r.isDefault == true).forEach(r => (r.isChecked = true));
      if (this.roles.filter(r => r.isDefault == true).length > 0)
        this.userRoles.push(this.roles.filter(r => r.isDefault == true)[0]);
    } else this.getUserRolesById(this.data.id);
  }
  async getUserRolesById(id: string): Promise<void> {
    this.userRoles = (await firstValueFrom(this.userService.getRolesById(id))).items;
    this.userRoles.forEach(u => (u.isChecked = true));
    this.userRoles.forEach(u => {
      this.roles.filter(r => r.id == u.id)[0].isChecked = true;
    });
  }
  async addOrUpdateUser() {
    if (!this.user.extraProperties.IsAdmin) {
      if (this.user.extraProperties.CustomerNo == '') {
        this.toaster.error('Müşteri Seçilmeden Kullanıcı Oluşturamazsınız!', 'Dikkat');
        return;
      }
    }
    if (!this.currentUser.roles.some(x => x == 'admin' || x == 'developer')) {
      var userName = this.user.userName?.toLocaleLowerCase('tr');
      if (userName.includes('admin') || userName.includes('developer')) {
        this.toaster.warn('Admin ve Developer kullanıcı adı alınamaz!', 'Dikkat');
        return;
      }
    }
    var tempUserRoleNames: string[] = [];
    this.userRoles.forEach(x => {
      tempUserRoleNames.push(x.name);
    });

    if (this.data.id == null) {
      var response = await firstValueFrom(this.userService.add(this.user));
      await firstValueFrom(this.userService.putRoles(response.id, tempUserRoleNames));
    } else {
      await firstValueFrom(this.userService.update(this.user.id, this.user));
      await firstValueFrom(this.userService.putRoles(this.user.id, tempUserRoleNames));
    }
    this.modalRef.close();
  }
  //#endregion

  //#region methods
  async ngOnInit(): Promise<void> {
    await this.loadRoles();
    if (this.data.id != null) {
      await this.getUserById(this.data.id);
    }
    if (!this.currentUserInfoService.isAdmin) {
      this.user.extraProperties.CustomerNo = this.currentUserInfoService.customerNo;
    }
  }
  changeUserRoles(roleId: string) {
    if (this.roles.filter(x => x.id == roleId)[0].isChecked)
      this.userRoles.push(this.roles.filter(x => x.id == roleId)[0]);
    else this.userRoles = this.userRoles.filter(x => x.id != roleId);
  }
  //#endregion
}
<div class="card">
  <div class="card-body p-3">
    <ul
      ngbNav
      #Border="ngbNav"
      [activeId]="1"
      class="nav nav-tabs nav-border-top nav-border-top-primary mb-3"
    >
      <li [ngbNavItem]="1">
        <a ngbNavLink> Kullanıcı Bilgileri </a>
        <ng-template ngbNavContent>
          <div class="form-group" *ngIf="currentUserInfoService.isAdmin">
            <div class="form-check form-switch form-check-success">
              <input
                class="form-check-input"
                [(ngModel)]="user.extraProperties.IsAdmin"
                type="checkbox"
                role="switch"
                id="flexSwitchCheckDefault2"
              />
              <label class="form-check-label" for="flexSwitchCheckDefault2">
                Admin Mi?</label
              >
            </div>
          </div>
          <div class="form-group" *ngIf="currentUserInfoService.isAdmin && !user.extraProperties.IsAdmin">
            <div class="mb-3">
              <label for="choices-single-default" class="form-label">Müşteri</label>

              <ng-select
                [items]="customers"
                bindLabel="title"
                bindValue="no"
                [(ngModel)]="user.extraProperties.CustomerNo"
              >
                <ng-template ng-option-tmp let-item="item">
                  <b>{{ item.no }}</b> - {{ item.title }}
                </ng-template>
              </ng-select>
            </div>
          </div>
          <div class="form-group">
            <div class="col-md-12">
              <label>Kullanıcı Adı *</label>
              <input
                required
                class="form-control"
                (focus)="(user.userName == null)"
                type="text"
                style="width: 100%"
                tabindex="0"
                [(ngModel)]="user.userName"
              />
            </div>
          </div>
          <div class="form-group row">
            <div class="col-md-6">
              <label>Adı</label>
              <input
                class="form-control"
                type="text"
                style="width: 100%"
                tabindex="1"
                [(ngModel)]="user.name"
              />
            </div>
            <div class="col-md-6">
              <label>Soyadı</label>
              <input
                class="form-control"
                type="text"
                style="width: 100%"
                tabindex="2"
                [(ngModel)]="user.surname"
              />
            </div>
          </div>
          <div class="form-group" *ngIf="this.data.id == null">
            <div class="col-md-12">
              <label>Şifre *</label>
              <input
                required
                class="form-control"
                (focus)="(user.password == null)"
                type="text"
                style="width: 100%"
                tabindex="0"
                [(ngModel)]="user.password"
              />
            </div>
          </div>
          <div class="form-group" *ngIf="this.data.id != null">
            <div class="col-md-12">
              <label>Yeni Şifre</label>
              <input
                class="form-control"
                (focus)="(false)"
                type="text"
                style="width: 100%"
                tabindex="0"
                placeholder="Şifre değiştirmek istiyorsanız giriniz"
                [(ngModel)]="user.password"
              />
            </div>
          </div>
          <div class="form-group">
            <div class="col-md-12">
              <label>E Posta Adresi *</label>
              <input
                required
                class="form-control"
                (focus)="(user.email == null)"
                type="email"
                style="width: 100%"
                tabindex="0"
                [(ngModel)]="user.email"
              />
            </div>
          </div>
          <div class="form-group">
            <div class="col-md-12">
              <label>Telefon Numarası</label>
              <input
                class="form-control"
                type="tel"
                style="width: 100%"
                tabindex="3"
                [(ngModel)]="user.phoneNumber"
              />
            </div>
          </div>
          <div class="form-group">
            <div class="form-check form-switch form-check-success">
              <input
                class="form-check-input"
                [(ngModel)]="user.isActive"
                type="checkbox"
                role="switch"
                id="flexSwitchCheckDefault"
              />
              <label class="form-check-label" for="flexSwitchCheckDefault">Aktif</label>
            </div>
          </div>
          <div class="form-group">
            <div class="form-check form-switch form-check-success">
              <input
                class="form-check-input"
                [(ngModel)]="user.lockoutEnabled"
                type="checkbox"
                role="switch"
                id="flexSwitchCheckDefault2"
              />
              <label class="form-check-label" for="flexSwitchCheckDefault2">
                Başarısız giriş denemeleri sonrası hesabı kitleme</label
              >
            </div>
          </div>
        </ng-template>
      </li>
      <li [ngbNavItem]="2" *ngIf="currentUserInfoService.isAdmin">
        <a ngbNavLink> Roller </a>
        <ng-template ngbNavContent>
          <div *ngFor="let role of roles">
            <div class="form-check form-check-danger mb-3">
              <input
                class="form-check-input"
                type="checkbox"
                id="{{ role.id }}"
                (change)="changeUserRoles(role.id)"
                [(ngModel)]="role.isChecked"
              />
              <label class="form-check-label" for="{{ role.id }}">
                {{ role.name }}
              </label>
            </div>
          </div>
        </ng-template>
      </li>
    </ul>
    <div [ngbNavOutlet]="Border"></div>
    <div class="text-center">
      <button
        type="button"
        class="btn btn-primary btn-small m-auto waves-effect waves-light"
        (click)="addOrUpdateUser()"
      >
        KAYDET
      </button>
    </div>
  </div>
</div>
